import { MakeLogicType, actions, kea, key, path, props, reducers, selectors } from 'kea'

import { validateWildcardLaunchUrl } from 'lib/components/AuthorizedUrlList/authorizedUrlListLogic'

export interface WildcardLaunchLogicProps {
    wildcardPattern: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface wildcardLaunchLogicValues {
    concreteUrl: string
    error: string | undefined
    showError: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface wildcardLaunchLogicActions {
    reset: () => {
        value: true
    }
    setConcreteUrl: (concreteUrl: string) => {
        concreteUrl: string
    }
    setShowError: (showError: boolean) => {
        showError: boolean
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface wildcardLaunchLogicMeta {
    key: string
    __keaTypeGenInternalSelectorTypes: {
        error: (concreteUrl: string, wildcardPattern: string) => string | undefined
    }
}

export type wildcardLaunchLogicType = MakeLogicType<
    wildcardLaunchLogicValues,
    wildcardLaunchLogicActions,
    WildcardLaunchLogicProps,
    wildcardLaunchLogicMeta
>

export const wildcardLaunchLogic = kea<wildcardLaunchLogicType>([
    props({} as WildcardLaunchLogicProps),
    key((props) => props.wildcardPattern),
    path((key) => ['scenes', 'toolbar-launch', 'wildcardLaunchLogic', key]),
    actions({
        setConcreteUrl: (concreteUrl: string) => ({ concreteUrl }),
        setShowError: (showError: boolean) => ({ showError }),
        reset: true,
    }),
    reducers({
        concreteUrl: [
            '',
            {
                setConcreteUrl: (_, { concreteUrl }) => concreteUrl,
                reset: () => '',
            },
        ],
        showError: [
            false,
            {
                setShowError: (_, { showError }) => showError,
                reset: () => false,
            },
        ],
    }),
    selectors({
        error: [
            (s, p) => [s.concreteUrl, p.wildcardPattern],
            (concreteUrl: string, wildcardPattern: string): string | undefined =>
                validateWildcardLaunchUrl(concreteUrl, wildcardPattern),
        ],
    }),
])
